SELECT COUNT(*)
FROM tb_enrollments
WHERE course_id = #{courseId}

SELECT EXISTS (
    SELECT 1
      FROM tb_attendance_records
     WHERE enrollment_id = #{enrollmentId}
       AND status IN ('PRESENT', 'LATE')
)

SELECT EXISTS (
    SELECT 1
      FROM tb_completions
     WHERE enrollment_id = #{enrollmentId}
       AND status IN ('ELIGIBLE', 'COMPLETED')
)
